                    if (qi <= ti) {
                        break;
                    }
                    var qm = /^-[ \t]+(.*?)[ \t]*$/.exec(ql.trim());
                    if (qm) {
                        items.push(unquote(qm[1].replace(/[ \t]+#.*$/, '').trim()));
                    }
                }
