    });

    test('stub keeps the workflow_dispatch entry path (AC4)', function () {
        assert.ok(extractJobIf(STUB).indexOf("github.event_name == 'workflow_dispatch'") !== -1,
            'dropping the dispatch path silently kills the SM reconciler loop');
