                var parts = [];
                for (var j = i + 1; j < lines.length; j++) {
                    if (/^\s*$/.test(lines[j])) continue;
                    if (/^ {5,}/.test(lines[j])) parts.push(lines[j].replace(/^\s+/, ''));
                    else break;
                }
                ifs.push(parts.join(' '));
            }
        }
        return ifs;
