        for (var j = i + 1; j < lines.length; j++) {
            var line = lines[j];
            if (line.trim() === '') {
                continue;
            }
            if (line.trim().charAt(0) === '#') {
                continue;
            }
            var indent = indentOf(line);
            if (indent === 0) {
                break;
            }
            var km = KEY_LINE_RE.exec(line.trim());
            if (!km) {
                continue;
            }
            if (childIndent === -1) {
                childIndent = indent;
            }
            if (indent !== childIndent) {
