            }
            if (unquote(km[2].trim()) !== 'issues') {
                continue;
            }
            // Inside the issues: block — the first `types:` key at its own
            // indent level; a dedent back to the issues level ends the scan.
            var typesIndent = -1;
            for (var k = j + 1; k < lines.length; k++) {
                var tl = lines[k];
                if (tl.trim() === '') {
                    continue;
                }
                if (tl.trim().charAt(0) === '#') {
