// Structural mapping-key lines of the block that OPENS after line
// `parentIdx` (its parent key sits at parentIndent): [{index, key,
// indent}]. Blank/comment lines are skipped, the child indent is pinned
// by the first key line (deper or shallower keys are not this block's
// direct children), and a line dedented to parentIndent ends the block.
function blockKeyLines(lines, parentIdx, parentIndent) {
   var out = [];
   var childIndent = -1;
   for (var j = parentIdx + 1; j < lines.length; j++) {
