Actually wait: original extractIssueTypes check was `m[1].replace(/[ \t]+#.*$/,').trim() !== ''` → continue. So block form ⟺ stripComment(m[1]).trim() === ''. Equivalent.

```javascript
// Structural mapping-key lines of the block that OPENS after line
// `parentIdx` (its parent key sits at parentIndent): [{index, key,
// indent}]. Blank/comment lines are skipped, the child indent is pinned
// by the first key line (deper or shallower keys are not this block's
// direct children), and a line dedented to parentIndent ends the block.
function blockKeyLines(lines, parentIdx, parentIndent) {
   var out = [];
   var childIndent = -1;
   for (var j = parentIdx + 1; j < lines.length; j++) {
       var line = lines[j];
       if (isSkippable(line)) {
           continue;
       }
       var indent = indentOf(line);
       if (indent <= parentIndent) {
           break;
       }
       var km = KEY_LINE_RE.exec(line.trim());
       if (!km) {
           continue;
       }
       if (childIndent === -1) {
           childIndent = indent;
       }
       if (indent !== childIndent) {
           continue;
       }
       out.push({ index: j, key: unquote(km[2].trim()), indent: indent });
   }
   return out;
}

// Index of the child key named `wanted` under the block at `parentIdx`;
// -1 when the block holds no such key.
function findChildKey(lines, parentIdx, parentIndent, wanted) {
   var keys = blockKeyLines(lines, parentIdx, parentIndent);
   for (var k = 0; k < keys.length; k++) {
       if (keys[k].key === wanted) {
           return keys[k].index;
       }
   }
   return -1;
}

// The `- item` entries of the block list opening after line `idx` (the
// list key sits at keyIndent); a line dedented to keyIndent ends the list.
function blockListItems(lines, idx, keyIndent) {
   var items = [];
   for (var q = idx + 1; q < lines.length; q++) {
       var ql = lines[q];
       if (ql.trim() === '') {
           continue;
       }
       var qi = indentOf(ql);
       if (qi <= keyIndent) {
           break;
       }
       var qm = /^-[ \t]+(.*?)[ \t]*$/.exec(ql.trim());
       if (qm) {
           items.push(unquote(stripComment(qm[1]).trim()));
       }
   }
   return items;
