// Strip a trailing ` # comment` from an inline YAML payload.
function stripComment(s) {
    return s.replace(/[ \t]+#.*$/, '');
}

// True when a line carries no YAML structure at all: blank or a full-line
// comment.
function isSkippable(line) {
    var t = line.trim();
